// Minimal stub for the LLVM-IR backend (M3 body-walk).
// Provides gs_print_i64 for the test-suite smoke check. The program's
// C main is generated by the IR's emit_program_entry (the IR's main
// calls the Goos main); the full runtime init (gs_rt_init, gs_gl
// setup) lands with the data-stack walk.
#include <stdio.h>
#include <stdint.h>

void gs_print_i64(int64_t val) {
    printf("%lld\n", (long long)val);
}
